def yaml_load(filename):
    if not is_safe_path(filename):
        raise ValueError("Invalid path")
    # Add explicit whitelisting of allowed directories
    allowed_dirs = {os.path.abspath("/safe_dir/"), os.path.abspath("/another_safe_dir/"), os.getcwd()}
    normalized_path = os.path.normpath(filename)
    if os.path.isabs(normalized_path) and os.path.abspath(normalized_path) not in allowed_dirs:
        raise ValueError("Invalid path")
    with open(filename, 'r') as file:
        data = yaml.safe_load(file)
